import{_ as t,o as n,c as r,ag as i}from"./chunks/framework.ySAk_w31.js";const m=JSON.parse(`{"title":"Produire et vérifier","description":"","frontmatter":{},"headers":[],"relativePath":"handout-03-produire-et-verifier.md","filePath":"handout-03-produire-et-verifier.md","handout":{"fichier":"handout-03-produire-et-verifier.md","markdown":"# Handout — Produire et vérifier\\n\\n**Développeur IA — Foundation · Zenika · fiche module 3**\\n\\nAvancer par petits pas sans perdre la maîtrise du code : la boucle de production, la relecture et les tests.\\n\\n## Feature par feature : la boucle\\n\\n_Module 3 · slide « Feature par feature : la boucle »_\\n\\n| Préparer                    | Livrer, puis feature suivante                                      |\\n| --------------------------- | ------------------------------------------------------------------ |\\n| 1. Lire le ticket           | 4. Implémenter une étape                                           |\\n| 2. Faire comprendre le code | 5. Tester et relire                                                |\\n| 3. Demande et plan validés  | 6. Commit : une étape = un commit (vert et relu, sinon retour à 4) |\\n|                             | 7. Étape suivante du plan                                          |\\n|                             | 8. Mettre à jour la doc projet                                     |\\n\\n- **Une étape = un commit** : chaque commit est un point de retour propre. Si une étape tourne mal, on revient au commit précédent au lieu de corriger par-dessus.\\n- **Étape 8** : ce qu'on a appris (un piège, une commande) remonte dans les instructions projet ou dans une skill.\\n\\n## Rewind plutôt qu'empiler\\n\\n_Module 3 · slide « Rewind plutôt qu'empiler »_\\n\\n| Empiler                                        | Rewind                                    |\\n| ---------------------------------------------- | ----------------------------------------- |\\n| Prompt flou                                    | Prompt flou                               |\\n| Code faux                                      | Code faux                                 |\\n| « Non, pas comme ça… » : on corrige par-dessus | On édite l'entrée : on revient en arrière |\\n| Context window plus sale                       | Nouvelle trajectoire propre               |\\n\\nEmpiler, c'est garder la réponse fausse **et** la correction dans tous les envois suivants. En pratique : éditer son message et relancer, ou revenir à un point antérieur de la session (certains harness restaurent aussi les fichiers). Sinon : revenir au dernier commit et ouvrir une nouvelle session avec le prompt corrigé.\\n\\n> Traitez une mauvaise sortie comme un **message du compilateur** : on corrige l'entrée, on relance.\\n\\n## Relire le code généré\\n\\n_Module 3 · slide « Relire le code généré »_\\n\\nLe code de l'agent se relit comme celui d'un **contributeur inconnu**. La grille, à cocher sur chaque diff :\\n\\n|     | Axe             | La question                                          |\\n| --- | --------------- | ---------------------------------------------------- |\\n| ☐   | **Correction**  | Résout-il vraiment le problème du ticket ?           |\\n| ☐   | **Cas limites** | Liste vide, \`null\`, dernière page, grandes valeurs ? |\\n| ☐   | **Sécurité**    | Entrées validées, autorisations correctes ?          |\\n| ☐   | **Performance** | Requêtes N+1, boucles, fuites mémoire ?              |\\n| ☐   | **Lisibilité**  | Compréhensible dans 6 mois, sans sur-ingénierie ?    |\\n| ☐   | **Dépendances** | Les imports et les API **existent-ils vraiment** ?   |\\n\\nFaites aussi relire l'agent par lui-même, de préférence dans une session neuve :\\n\\n\`\`\`text\\nRelis le diff que tu viens de produire :\\ncas limites, sécurité, perf.\\n\`\`\`\\n\\n> Le vrai danger : l'**incompétence cachée**, du code qui a l'air bon. L'agent peut se relire, mais c'est **vous** qui décidez.\\n\\n## Deux natures de tests, deux publics\\n\\n_Module 3 · slide « Deux natures de tests, deux publics »_\\n\\n|                       | **Tests de construction**                           | **Tests fonctionnels**                             |\\n| --------------------- | --------------------------------------------------- | -------------------------------------------------- |\\n| **À qui ils servent** | à **l'agent**, pour se contrôler pendant qu'il code | à **l'équipe**, pour savoir ce que fait le produit |\\n| **Ce qu'ils testent** | l'implémentation, unité par unité                   | le **comportement observable** de l'API            |\\n| **Durée de vie**      | jetables                                            | durables : ils _sont_ la spec exécutable           |\\n\\n- Un test fonctionnel est un contrat : « GET /bookings renvoie un nextCursor tant qu'il reste des résultats ». C'est celui-là qu'on relit ligne à ligne.\\n- **Faux succès** : un agent peut affaiblir ou supprimer un test pour le faire passer. On relit les tests comme le code.\\n- Le coût de production d'un test a chuté, le coût de maintenance n'a pas bougé.\\n\\n> **En fin de feature**, là où les deux se recouvrent, **le test fonctionnel gagne** : on supprime le doublon.\\n\\n## Brownfield : comprendre et figer avant de modifier\\n\\n_Module 3 · slide « Brownfield : comprendre et figer avant de modifier »_\\n\\n**Pas tout le code d'un coup** : 500 000 lignes ≈ des millions de tokens, ça ne rentre pas. L'agent **navigue** (recherche, lecture ciblée) ; on attaque **par morceaux** : un module, un endpoint.\\n\\n**Faire comprendre** : demander à l'agent d'expliquer le flux de GET /bookings, de la route à la base, avant de le modifier. Si l'explication est fausse, le code le serait aussi.\\n\\n**Figer le comportement actuel** avec des tests de caractérisation :\\n\\n\`\`\`text\\nAvant de toucher à BookingsController,\\nécris des tests qui capturent le\\ncomportement ACTUEL de GET /bookings,\\nmême s'il est faux.\\n\`\`\`\\n\\nCes tests détectent le **changement**, pas la correction : forme de la réponse, tri, filtres. Si la pagination casse le tri, un test le dit. Un test de caractérisation qui fige un bug est signalé comme tel.\\n\\n> **Faire comprendre avant de faire modifier** : une explication relue vaut mieux qu'un diff incompris.\\n\\n## Revue IA : donner le contexte du diff\\n\\n_Module 3 · slide « Revue IA : donner le contexte du diff »_\\n\\n| Donner à l'agent relecteur                   | Pourquoi                                   |\\n| -------------------------------------------- | ------------------------------------------ |\\n| **Le diff complet**, avec du contexte autour | voir la fonction entière, pas trois lignes |\\n| **Le ticket**, la demande initiale, le plan  | juger le code sur l'intention              |\\n| **Les conventions** (instructions projet)    | relever les écarts propres à l'équipe      |\\n| **La grille** « Relire le code généré »      | chercher les défauts, pas complimenter     |\\n\\n- Plus de lignes de contexte autour du changement réduit les faux positifs : par exemple \`git diff -U10\` au lieu des 3 lignes par défaut.\\n- Une **session neuve** fait un meilleur relecteur que celle qui a écrit le code : elle n'a pas son historique de décisions.\\n\\n> La revue IA **aide** l'humain, elle ne **décide** pas : c'est un humain qui valide avant le merge.\\n\\n## À retenir\\n\\n1. Petits pas, **un commit par étape**.\\n2. **Rewind** plutôt qu'empiler.\\n3. Des **tests** comme filet et comme spec, relus comme le code.\\n4. Une **relecture humaine** avant le merge.\\n\\n**Mots-clés** : rewind, autorégression, brownfield / greenfield, tests de caractérisation, revue IA, hallucination, human-in-the-loop — voir le glossaire.\\n"}}`),o={name:"handout-03-produire-et-verifier.md"};function s(a,e,l,d,u,c){return n(),r("div",null,[...e[0]||(e[0]=[i(`<p class="zh-type">fiche module 3</p><h1 id="handout-produire-et-verifier" tabindex="-1">Produire et vérifier <a class="header-anchor" href="#handout-produire-et-verifier" aria-label="Permalink to &quot;Handout — Produire et vérifier&quot;">​</a></h1><p>Avancer par petits pas sans perdre la maîtrise du code : la boucle de production, la relecture et les tests.</p><h2 id="feature-par-feature-la-boucle" tabindex="-1">Feature par feature : la boucle <a class="header-anchor" href="#feature-par-feature-la-boucle" aria-label="Permalink to &quot;Feature par feature : la boucle&quot;">​</a></h2><p><em>Module 3 · slide « Feature par feature : la boucle »</em></p><table tabindex="0"><thead><tr><th>Préparer</th><th>Livrer, puis feature suivante</th></tr></thead><tbody><tr><td>1. Lire le ticket</td><td>4. Implémenter une étape</td></tr><tr><td>2. Faire comprendre le code</td><td>5. Tester et relire</td></tr><tr><td>3. Demande et plan validés</td><td>6. Commit : une étape = un commit (vert et relu, sinon retour à 4)</td></tr><tr><td></td><td>7. Étape suivante du plan</td></tr><tr><td></td><td>8. Mettre à jour la doc projet</td></tr></tbody></table><ul><li><strong>Une étape = un commit</strong> : chaque commit est un point de retour propre. Si une étape tourne mal, on revient au commit précédent au lieu de corriger par-dessus.</li><li><strong>Étape 8</strong> : ce qu’on a appris (un piège, une commande) remonte dans les instructions projet ou dans une skill.</li></ul><h2 id="rewind-plutot-qu-empiler" tabindex="-1">Rewind plutôt qu’empiler <a class="header-anchor" href="#rewind-plutot-qu-empiler" aria-label="Permalink to &quot;Rewind plutôt qu&#39;empiler&quot;">​</a></h2><p><em>Module 3 · slide « Rewind plutôt qu’empiler »</em></p><table tabindex="0"><thead><tr><th>Empiler</th><th>Rewind</th></tr></thead><tbody><tr><td>Prompt flou</td><td>Prompt flou</td></tr><tr><td>Code faux</td><td>Code faux</td></tr><tr><td>« Non, pas comme ça… » : on corrige par-dessus</td><td>On édite l’entrée : on revient en arrière</td></tr><tr><td>Context window plus sale</td><td>Nouvelle trajectoire propre</td></tr></tbody></table><p>Empiler, c’est garder la réponse fausse <strong>et</strong> la correction dans tous les envois suivants. En pratique : éditer son message et relancer, ou revenir à un point antérieur de la session (certains harness restaurent aussi les fichiers). Sinon : revenir au dernier commit et ouvrir une nouvelle session avec le prompt corrigé.</p><blockquote><p>Traitez une mauvaise sortie comme un <strong>message du compilateur</strong> : on corrige l’entrée, on relance.</p></blockquote><h2 id="relire-le-code-genere" tabindex="-1">Relire le code généré <a class="header-anchor" href="#relire-le-code-genere" aria-label="Permalink to &quot;Relire le code généré&quot;">​</a></h2><p><em>Module 3 · slide « Relire le code généré »</em></p><p>Le code de l’agent se relit comme celui d’un <strong>contributeur inconnu</strong>. La grille, à cocher sur chaque diff :</p><table tabindex="0"><thead><tr><th></th><th>Axe</th><th>La question</th></tr></thead><tbody><tr><td>☐</td><td><strong>Correction</strong></td><td>Résout-il vraiment le problème du ticket ?</td></tr><tr><td>☐</td><td><strong>Cas limites</strong></td><td>Liste vide, <code>null</code>, dernière page, grandes valeurs ?</td></tr><tr><td>☐</td><td><strong>Sécurité</strong></td><td>Entrées validées, autorisations correctes ?</td></tr><tr><td>☐</td><td><strong>Performance</strong></td><td>Requêtes N+1, boucles, fuites mémoire ?</td></tr><tr><td>☐</td><td><strong>Lisibilité</strong></td><td>Compréhensible dans 6 mois, sans sur-ingénierie ?</td></tr><tr><td>☐</td><td><strong>Dépendances</strong></td><td>Les imports et les API <strong>existent-ils vraiment</strong> ?</td></tr></tbody></table><p>Faites aussi relire l’agent par lui-même, de préférence dans une session neuve :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Relis le diff que tu viens de produire :</span></span>
<span class="line"><span>cas limites, sécurité, perf.</span></span></code></pre></div><blockquote><p>Le vrai danger : l’<strong>incompétence cachée</strong>, du code qui a l’air bon. L’agent peut se relire, mais c’est <strong>vous</strong> qui décidez.</p></blockquote><h2 id="deux-natures-de-tests-deux-publics" tabindex="-1">Deux natures de tests, deux publics <a class="header-anchor" href="#deux-natures-de-tests-deux-publics" aria-label="Permalink to &quot;Deux natures de tests, deux publics&quot;">​</a></h2><p><em>Module 3 · slide « Deux natures de tests, deux publics »</em></p><table tabindex="0"><thead><tr><th></th><th><strong>Tests de construction</strong></th><th><strong>Tests fonctionnels</strong></th></tr></thead><tbody><tr><td><strong>À qui ils servent</strong></td><td>à <strong>l’agent</strong>, pour se contrôler pendant qu’il code</td><td>à <strong>l’équipe</strong>, pour savoir ce que fait le produit</td></tr><tr><td><strong>Ce qu’ils testent</strong></td><td>l’implémentation, unité par unité</td><td>le <strong>comportement observable</strong> de l’API</td></tr><tr><td><strong>Durée de vie</strong></td><td>jetables</td><td>durables : ils <em>sont</em> la spec exécutable</td></tr></tbody></table><ul><li>Un test fonctionnel est un contrat : « GET /bookings renvoie un nextCursor tant qu’il reste des résultats ». C’est celui-là qu’on relit ligne à ligne.</li><li><strong>Faux succès</strong> : un agent peut affaiblir ou supprimer un test pour le faire passer. On relit les tests comme le code.</li><li>Le coût de production d’un test a chuté, le coût de maintenance n’a pas bougé.</li></ul><blockquote><p><strong>En fin de feature</strong>, là où les deux se recouvrent, <strong>le test fonctionnel gagne</strong> : on supprime le doublon.</p></blockquote><h2 id="brownfield-comprendre-et-figer-avant-de-modifier" tabindex="-1">Brownfield : comprendre et figer avant de modifier <a class="header-anchor" href="#brownfield-comprendre-et-figer-avant-de-modifier" aria-label="Permalink to &quot;Brownfield : comprendre et figer avant de modifier&quot;">​</a></h2><p><em>Module 3 · slide « Brownfield : comprendre et figer avant de modifier »</em></p><p><strong>Pas tout le code d’un coup</strong> : 500 000 lignes ≈ des millions de tokens, ça ne rentre pas. L’agent <strong>navigue</strong> (recherche, lecture ciblée) ; on attaque <strong>par morceaux</strong> : un module, un endpoint.</p><p><strong>Faire comprendre</strong> : demander à l’agent d’expliquer le flux de GET /bookings, de la route à la base, avant de le modifier. Si l’explication est fausse, le code le serait aussi.</p><p><strong>Figer le comportement actuel</strong> avec des tests de caractérisation :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avant de toucher à BookingsController,</span></span>
<span class="line"><span>écris des tests qui capturent le</span></span>
<span class="line"><span>comportement ACTUEL de GET /bookings,</span></span>
<span class="line"><span>même s&#39;il est faux.</span></span></code></pre></div><p>Ces tests détectent le <strong>changement</strong>, pas la correction : forme de la réponse, tri, filtres. Si la pagination casse le tri, un test le dit. Un test de caractérisation qui fige un bug est signalé comme tel.</p><blockquote><p><strong>Faire comprendre avant de faire modifier</strong> : une explication relue vaut mieux qu’un diff incompris.</p></blockquote><h2 id="revue-ia-donner-le-contexte-du-diff" tabindex="-1">Revue IA : donner le contexte du diff <a class="header-anchor" href="#revue-ia-donner-le-contexte-du-diff" aria-label="Permalink to &quot;Revue IA : donner le contexte du diff&quot;">​</a></h2><p><em>Module 3 · slide « Revue IA : donner le contexte du diff »</em></p><table tabindex="0"><thead><tr><th>Donner à l’agent relecteur</th><th>Pourquoi</th></tr></thead><tbody><tr><td><strong>Le diff complet</strong>, avec du contexte autour</td><td>voir la fonction entière, pas trois lignes</td></tr><tr><td><strong>Le ticket</strong>, la demande initiale, le plan</td><td>juger le code sur l’intention</td></tr><tr><td><strong>Les conventions</strong> (instructions projet)</td><td>relever les écarts propres à l’équipe</td></tr><tr><td><strong>La grille</strong> « Relire le code généré »</td><td>chercher les défauts, pas complimenter</td></tr></tbody></table><ul><li>Plus de lignes de contexte autour du changement réduit les faux positifs : par exemple <code>git diff -U10</code> au lieu des 3 lignes par défaut.</li><li>Une <strong>session neuve</strong> fait un meilleur relecteur que celle qui a écrit le code : elle n’a pas son historique de décisions.</li></ul><blockquote><p>La revue IA <strong>aide</strong> l’humain, elle ne <strong>décide</strong> pas : c’est un humain qui valide avant le merge.</p></blockquote><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>Petits pas, <strong>un commit par étape</strong>.</li><li><strong>Rewind</strong> plutôt qu’empiler.</li><li>Des <strong>tests</strong> comme filet et comme spec, relus comme le code.</li><li>Une <strong>relecture humaine</strong> avant le merge.</li></ol><p><strong>Mots-clés</strong> : rewind, autorégression, brownfield / greenfield, tests de caractérisation, revue IA, hallucination, human-in-the-loop — voir le glossaire.</p>`,40)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
